    def test_schema_checking_type_mismatch(self):
        from autodebug.detection.contract_drift import ContractDriftDetector, DriftType
        detector = ContractDriftDetector()
        detector.load_spec_from_dict(self._make_spec())
        transcript = {
            "http": [
                {
                    "method": "GET",
                    "url": "http://localhost/users",
                    "status": 200,
                    "response_body": {"id": "not_an_int", "name": "Alice"},  # id should be int
                }
            ]
        }
        result = detector.analyze_transcript(transcript)
        type_mismatches = [d for d in result.drifts if d.drift_type == DriftType.TYPE_MISMATCH]
        assert len(type_mismatches) >= 1

